//! The frozen repository. CLI-free: no clap, no standout, no environment.

/// A commit in the frozen repository.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Commit {
    pub hash: &'static str,
    pub author: &'static str,
    pub message: &'static str,
}

/// A branch, named by its full ref path.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Ref {
    pub name: &'static str,
    pub hash: &'static str,
}

/// Commits, newest first.
const COMMITS: &[Commit] = &[
    Commit { hash: "a3f4", author: "alice", message: "Fix off-by-one" },
    Commit { hash: "b7e2", author: "bob", message: "Add parser" },
    Commit { hash: "c1a9", author: "alice", message: "Initial import" },
];

const REFS: &[Ref] = &[
    Ref { name: "refs/heads/dev", hash: "b7e2" },
    Ref { name: "refs/heads/main", hash: "a3f4" },
];

const CURRENT_BRANCH: &str = "main";

/// The commits, newest first.
pub fn commits() -> &'static [Commit] {
    COMMITS
}

/// The newest `limit` commits, or all of them when unlimited.
pub fn log(limit: Option<usize>) -> &'static [Commit] {
    match limit {
        Some(n) => &COMMITS[..n.min(COMMITS.len())],
        None => COMMITS,
    }
}

/// Every branch ref, sorted by ref name.
pub fn refs() -> Vec<Ref> {
    let mut refs = REFS.to_vec();
    refs.sort_by_key(|r| r.name);
    refs
}

/// The branch HEAD is on.
pub fn current_branch() -> &'static str {
    CURRENT_BRANCH
}

/// The commit HEAD points at.
pub fn head() -> &'static Commit {
    let hash = refs()
        .iter()
        .find(|r| r.name == format!("refs/heads/{CURRENT_BRANCH}"))
        .map(|r| r.hash)
        .expect("the current branch always exists");
    find(hash).expect("the current branch always points at a commit")
}

/// The commit with `hash`, if the repository has one.
pub fn find(hash: &str) -> Option<&'static Commit> {
    COMMITS.iter().find(|c| c.hash == hash)
}

