//! Configuration resolution. CLI-free: callers supply the paths, this module
//! reads and merges them.
//!
//! Precedence, highest first: command-line flags (applied by the caller), the
//! nearest `.gitlike.toml` walking up from the working directory, the user
//! config file, built-in defaults.

use std::fmt;
use std::path::{Path, PathBuf};

/// The file a directory walk looks for.
pub const LOCAL_FILE_NAME: &str = ".gitlike.toml";

/// The recognized configuration keys.
pub const LOG_LIMIT: &str = "log.limit";
pub const USER_NAME: &str = "user.name";

/// The effective configuration, after merging every source.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Config {
    pub log_limit: Option<u64>,
    pub user_name: Option<String>,
}

impl Config {
    /// The effective value of `key`, rendered for display, or `None` when the
    /// key is unset or unknown.
    pub fn get(&self, key: &str) -> Option<String> {
        match key {
            LOG_LIMIT => self.log_limit.map(|limit| limit.to_string()),
            USER_NAME => self.user_name.clone(),
            _ => None,
        }
    }

    /// Merge `other` underneath `self`: `self` wins key by key.
    fn under(mut self, other: Config) -> Config {
        self.log_limit = self.log_limit.or(other.log_limit);
        self.user_name = self.user_name.or(other.user_name);
        self
    }
}

/// A configuration file that exists but cannot be used.
#[derive(Debug)]
pub struct ConfigError {
    path: PathBuf,
    message: String,
}

impl ConfigError {
    fn new(path: &Path, message: impl Into<String>) -> Self {
        ConfigError { path: path.to_path_buf(), message: message.into() }
    }
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}: {}", self.path.display(), self.message)
    }
}

impl std::error::Error for ConfigError {}

/// Resolve the configuration for a working directory and a user config path.
///
/// `start_dir` is walked upwards toward the filesystem root; the first
/// `.gitlike.toml` found wins and files further up are not merged. `user_file`
/// is consulted for keys the local file leaves unset.
pub fn resolve(start_dir: &Path, user_file: Option<&Path>) -> Result<Config, ConfigError> {
    let local = match find_local(start_dir) {
        Some(path) => read(&path)?,
        None => Config::default(),
    };
    let user = match user_file {
        Some(path) if path.is_file() => read(path)?,
        _ => Config::default(),
    };
    Ok(local.under(user))
}

/// The nearest `.gitlike.toml`, walking up from `start_dir`.
pub fn find_local(start_dir: &Path) -> Option<PathBuf> {
    let mut dir = Some(start_dir);
    while let Some(current) = dir {
        let candidate = current.join(LOCAL_FILE_NAME);
        if candidate.is_file() {
            return Some(candidate);
        }
        dir = current.parent();
    }
    None
}

/// Read one TOML config file. Both `log.limit = 2` and the `[log]` table form
/// parse to the same thing.
pub fn read(path: &Path) -> Result<Config, ConfigError> {
    let text = std::fs::read_to_string(path)
        .map_err(|error| ConfigError::new(path, error.to_string()))?;
    parse(&text).map_err(|message| ConfigError::new(path, message))
}

fn parse(text: &str) -> Result<Config, String> {
    let document: toml::Value = text.parse().map_err(|error: toml::de::Error| {
        error.message().to_string()
    })?;

    let mut config = Config::default();

    if let Some(value) = lookup(&document, LOG_LIMIT) {
        let limit = value
            .as_integer()
            .filter(|limit| *limit > 0)
            .ok_or_else(|| format!("{LOG_LIMIT} must be a positive integer"))?;
        config.log_limit = Some(limit as u64);
    }

    if let Some(value) = lookup(&document, USER_NAME) {
        let name = value
            .as_str()
            .ok_or_else(|| format!("{USER_NAME} must be a string"))?;
        config.user_name = Some(name.to_string());
    }

    Ok(config)
}

fn lookup<'a>(document: &'a toml::Value, key: &str) -> Option<&'a toml::Value> {
    key.split('.')
        .try_fold(document, |value, segment| value.get(segment))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn both_toml_spellings_mean_the_same_thing() {
        let dotted = parse("log.limit = 2").unwrap();
        let table = parse("[log]\nlimit = 2\n").unwrap();
        assert_eq!(dotted, table);
        assert_eq!(dotted.log_limit, Some(2));
    }

    #[test]
    fn unset_keys_have_no_value() {
        let config = parse("user.name = \"alice\"").unwrap();
        assert_eq!(config.get(USER_NAME).as_deref(), Some("alice"));
        assert_eq!(config.get(LOG_LIMIT), None);
        assert_eq!(config.get("no.such.key"), None);
    }

    #[test]
    fn a_limit_must_be_a_positive_integer() {
        assert!(parse("log.limit = 0").is_err());
        assert!(parse("log.limit = -1").is_err());
        assert!(parse("log.limit = \"2\"").is_err());
    }

    #[test]
    fn the_nearer_file_wins_key_by_key_over_the_user_file() {
        let local = Config { log_limit: Some(1), user_name: None };
        let user = Config { log_limit: Some(9), user_name: Some("bob".into()) };
        let merged = local.under(user);
        assert_eq!(merged.log_limit, Some(1));
        assert_eq!(merged.user_name.as_deref(), Some("bob"));
    }
}
