//! Plumbing commands.
//!
//! Plumbing output is a stability contract: byte-identical regardless of theme,
//! `--output` mode, terminal vs pipe, or environment, and never paged. It
//! therefore does not go through the presentation layer at all — standout owns
//! porcelain, and hands these commands back unhandled (the documented partial
//! adoption seam) so their bytes stay exactly what a script was promised.

use std::io::{self, Write};

use clap::ArgMatches;
use gitlike::config::Config;
use gitlike::repo;

/// Run the plumbing command named by `matches` and report its exit status.
pub fn dispatch(matches: &ArgMatches, config: &Config) -> i32 {
    match matches.subcommand() {
        Some(("ref-list", _)) => ref_list(),
        Some(("cat-object", sub)) => cat_object(argument(sub, "hash")),
        Some(("config", sub)) => match sub.subcommand() {
            Some(("get", get)) => config_get(config, argument(get, "key")),
            _ => unreachable(),
        },
        _ => unreachable(),
    }
}

/// One line per branch, sorted by ref name.
fn ref_list() -> i32 {
    let mut body = String::new();
    for reference in repo::refs() {
        body.push_str(&format!("{} {}\n", reference.hash, reference.name));
    }
    write_stdout(&body)
}

/// The object body for a known hash; exit 3 and a diagnostic for anything else.
fn cat_object(hash: &str) -> i32 {
    match repo::find(hash) {
        Some(commit) => write_stdout(&format!(
            "author {}\nmessage {}\n",
            commit.author, commit.message
        )),
        None => {
            write_stderr(&format!("gitlike: no such object: {hash}\n"));
            3
        }
    }
}

/// The effective value of a key; exit 1 and total silence when it has none.
fn config_get(config: &Config, key: &str) -> i32 {
    match config.get(key) {
        Some(value) => write_stdout(&format!("{value}\n")),
        None => 1,
    }
}

fn argument<'a>(matches: &'a ArgMatches, name: &str) -> &'a str {
    matches
        .get_one::<String>(name)
        .map(String::as_str)
        .expect("clap requires this argument")
}

fn unreachable() -> i32 {
    write_stderr("gitlike: unknown command\n");
    2
}

fn write_stdout(body: &str) -> i32 {
    let mut stdout = io::stdout().lock();
    match stdout.write_all(body.as_bytes()).and_then(|()| stdout.flush()) {
        Ok(()) => 0,
        // A consumer that stopped reading early is not a failure.
        Err(error) if error.kind() == io::ErrorKind::BrokenPipe => 0,
        Err(error) => {
            write_stderr(&format!("gitlike: {error}\n"));
            1
        }
    }
}

fn write_stderr(body: &str) {
    let mut stderr = io::stderr().lock();
    let _ = stderr.write_all(body.as_bytes());
    let _ = stderr.flush();
}
EOF
