cat > src/main.rs <<'EOF'
//! `gitlike` — a tiny version-control inspector.
//!
//! Porcelain (`log`, `status`) is standout's: templates, themes, output modes,
//! and the pager. Plumbing (`ref-list`, `cat-object`, `config get`) writes a
//! fixed byte stream and bypasses presentation entirely.

mod handlers;
mod plumbing;
mod view;

use std::io::{self, IsTerminal, Write};
use std::path::PathBuf;
use std::process::{Command as Process, Stdio};

use clap::{CommandFactory, Parser, Subcommand};
use gitlike::config::{self, Config};
use standout::cli::{App, RunResult, SuccessKind};
use standout::{embed_styles, embed_templates};

#[derive(Parser)]
#[command(name = "gitlike", version, about = "A tiny version-control inspector")]
struct Cli {
    /// Do not send output through a pager.
    #[arg(long, global = true)]
    no_pager: bool,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Show the commit log, newest first.
    Log {
        /// Show at most N commits, overriding any configured log.limit.
        #[arg(long, value_name = "N", value_parser = clap::value_parser!(u64).range(1..))]
        limit: Option<u64>,
    },
    /// Show the current branch and HEAD.
    Status,
    /// List every branch ref (plumbing).
    #[command(name = "ref-list")]
    RefList,
    /// Print the body of an object (plumbing).
    #[command(name = "cat-object")]
    CatObject {
        /// The object hash.
        hash: String,
    },
    /// Inspect configuration.
    Config {
        #[command(subcommand)]
        action: ConfigAction,
    },
}

#[derive(Subcommand)]
enum ConfigAction {
    /// Print the effective value of a key.
    Get {
        /// The configuration key, such as `log.limit`.
        key: String,
    },
}

fn main() {
    std::process::exit(run());
}

fn run() -> i32 {
    let config = match load_config() {
        Ok(config) => config,
        Err(message) => return fail(&message),
    };

    let app = match App::builder()
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme(theme_name())
        .app_state(config.clone())
        .command_with("log", handlers::log__handler, |command| {
            command.template_name("log")
        })
        .and_then(|builder| {
            builder.command_with("status", handlers::status__handler, |command| {
                command.template_name("status")
            })
        })
        .and_then(|builder| builder.build())
    {
        Ok(app) => app,
        Err(error) => return fail(&error.to_string()),
    };

    match app.run_to_string(Cli::command(), std::env::args()) {
        RunResult::Handled(output) => {
            let pageable = matches!(output.kind(), SuccessKind::Command);
            emit(output.as_str(), pageable)
        }
        // Plumbing is deliberately unregistered; it owns its own bytes.
        RunResult::NoMatch(matches) => plumbing::dispatch(&matches, &config),
        RunResult::Error(error) => {
            write_stderr(&terminated(&error.to_string()));
            error.exit_status().code().into()
        }
        RunResult::Silent => 0,
        _ => 0,
    }
}

/// Resolve configuration from the working directory and the user config file.
fn load_config() -> Result<Config, String> {
    let cwd = std::env::current_dir().map_err(|error| error.to_string())?;
    config::resolve(&cwd, user_config_path().as_deref()).map_err(|error| error.to_string())
}

fn user_config_path() -> Option<PathBuf> {
    if let Some(home) = env_value("GITLIKE_CONFIG_HOME") {
        return Some(PathBuf::from(home).join("config.toml"));
    }
    env_value("HOME").map(|home| PathBuf::from(home).join(".config/gitlike/config.toml"))
}

/// The active theme. `NO_COLOR` means unstyled whatever else was asked for.
fn theme_name() -> &'static str {
    if std::env::var_os("NO_COLOR").is_some() {
        return "mono";
    }
    match env_value("GITLIKE_THEME").as_deref() {
        Some("mono") => "mono",
        _ => "default",
    }
}

/// Write porcelain output, through the pager when one is warranted.
fn emit(text: &str, pageable: bool) -> i32 {
    let body = terminated(text);
    if pageable && !no_pager_requested() && io::stdout().is_terminal() {
        if let Some(pager) = pager_command() {
            return page(&body, &pager);
        }
    }
    write_stdout(&body)
}

/// `--no-pager` is read straight from the command line: the decision to page
/// happens outside dispatch, after rendering, so there are no matches to ask.
fn no_pager_requested() -> bool {
    std::env::args().any(|argument| argument == "--no-pager")
}

/// `GITLIKE_PAGER`, else `PAGER`. The first one that is set decides, so an
/// empty value disables paging rather than falling through.
fn pager_command() -> Option<String> {
    for name in ["GITLIKE_PAGER", "PAGER"] {
        if let Ok(value) = std::env::var(name) {
            return (!value.trim().is_empty()).then_some(value);
        }
    }
    None
}

fn page(body: &str, pager: &str) -> i32 {
    let child = Process::new("sh")
        .arg("-c")
        .arg(pager)
        .stdin(Stdio::piped())
        .spawn();

    let mut child = match child {
        Ok(child) => child,
        // No pager to be had; output is never lost to a missing one.
        Err(_) => return write_stdout(body),
    };

    if let Some(mut stdin) = child.stdin.take() {
        let _ = stdin.write_all(body.as_bytes());
    }
    let _ = child.wait();
    0
}

/// Exactly one trailing newline on non-empty output, so template whitespace
/// never leaks into the contract.
fn terminated(text: &str) -> String {
    let body = text.trim_end_matches('\n');
    if body.is_empty() {
        String::new()
    } else {
        format!("{body}\n")
    }
}

fn env_value(name: &str) -> Option<String> {
    std::env::var(name).ok().filter(|value| !value.is_empty())
}

fn fail(message: &str) -> i32 {
    write_stderr(&format!("gitlike: {message}\n"));
    1
}

fn write_stdout(body: &str) -> i32 {
    let mut stdout = io::stdout().lock();
    match stdout.write_all(body.as_bytes()).and_then(|()| stdout.flush()) {
        Ok(()) => 0,
        Err(error) if error.kind() == io::ErrorKind::BrokenPipe => 0,
        Err(error) => fail(&error.to_string()),
    }
}

fn write_stderr(body: &str) {
    let mut stderr = io::stderr().lock();
    let _ = stderr.write_all(body.as_bytes());
    let _ = stderr.flush();
}
