//! Porcelain handlers: CLI adapters over the core, returning view data for
//! standout to render.

use anyhow::Error;
use gitlike::config::Config;
use gitlike::repo;
use standout::cli::{CommandContext, Output};
use standout::handler;

use crate::view::{CommitView, LogView, StatusView};

#[handler]
pub fn log(
    #[arg] limit: Option<u64>,
    #[ctx] ctx: &CommandContext,
) -> Result<Output<LogView>, Error> {
    let config = ctx.app_state.get_required::<Config>()?;
    // The flag outranks any configured limit; with neither, the log is uncapped.
    let effective = limit.or(config.log_limit).map(|limit| limit as usize);

    Ok(Output::Render(LogView {
        commits: repo::log(effective).iter().map(CommitView::from).collect(),
    }))
}

#[handler]
pub fn status() -> Result<Output<StatusView>, Error> {
    let head = repo::head();

    Ok(Output::Render(StatusView {
        branch: repo::current_branch().to_string(),
        hash: head.hash.to_string(),
        message: head.message.to_string(),
    }))
}
