//! End-to-end tests over the real binary: the spec is about bytes and exit
//! statuses, so these assert on exactly those.

use std::path::{Path, PathBuf};
use std::process::Command;

struct Run {
    stdout: String,
    stderr: String,
    code: i32,
}

/// A private working directory with no config anywhere near it.
fn scratch(name: &str) -> PathBuf {
    let dir = std::env::temp_dir().join("gitlike-tests").join(name);
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("scratch dir");
    dir
}

fn run(dir: &Path, args: &[&str], env: &[(&str, &str)]) -> Run {
    let mut command = Command::new(env!("CARGO_BIN_EXE_gitlike"));
    command
        .current_dir(dir)
        .args(args)
        // Neutralize the ambient environment; each test opts back in.
        .env_remove("GITLIKE_PAGER")
        .env_remove("PAGER")
        .env_remove("NO_COLOR")
        .env_remove("GITLIKE_THEME")
        .env("HOME", dir.join("home"))
        .env("GITLIKE_CONFIG_HOME", dir.join("config"));
    for (key, value) in env {
        command.env(key, value);
    }

    let output = command.output().expect("gitlike runs");
    Run {
        stdout: String::from_utf8(output.stdout).expect("utf-8 stdout"),
        stderr: String::from_utf8(output.stderr).expect("utf-8 stderr"),
        code: output.status.code().expect("an exit status"),
    }
}

