    let nested = dir.join("nested/deeper");
    std::fs::create_dir_all(&nested).unwrap();
    std::fs::write(dir.join(".gitlike.toml"), "log.limit = 1\nuser.name = \"far\"\n").unwrap();
    std::fs::write(nested.join(".gitlike.toml"), "log.limit = 2\n").unwrap();

