/// `log.limit` is a positive integer wherever it comes from.
fn positive_limit(value: &str) -> Result<u64, String> {
    match value.parse::<u64>() {
        Ok(limit) if limit > 0 => Ok(limit),
        _ => Err("expected a positive integer".to_string()),
    }
}

fn main() {
    std::process::exit(run());
}

fn run() -> i32 {
    let config = match load_config() {
        Ok(config) => config,
        Err(message) => return fail(&message),
    };

    let app = match App::builder()
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme(theme_name())
        .app_state(config.clone())
        .command_with("log", handlers::log__handler, |command| {
            command.template("log")
        })
        .and_then(|builder| {
            builder.command_with("status", handlers::status__handler, |command| {
                command.template("status")
            })
        })
        .and_then(|builder| builder.build())
    {
        Ok(app) => app,
        Err(error) => return fail(&error.to_string()),
    };

    match app.run_to_string(Cli::command(), std::env::args()) {
        RunResult::Handled(output) => {
            let pageable = matches!(output.kind(), SuccessKind::Command);
            emit(output.as_str(), pageable)
        }
        // Plumbing is deliberately unregistered; it owns its own bytes.
        RunResult::NoMatch(matches) => plumbing::dispatch(&matches, &config),
        RunResult::Error(error) => {
            write_stderr(&terminated(error.as_ref()));
            error.exit_status().code().into()
        }
        RunResult::Silent => 0,
        _ => 0,
    }
}

/// Resolve configuration from the working directory and the user config file.
fn load_config() -> Result<Config, String> {
    let cwd = std::env::current_dir().map_err(|error| error.to_string())?;
    config::resolve(&cwd, user_config_path().as_deref()).map_err(|error| error.to_string())
}

